pipeline.runs:
tmpdir="$(mktemp -d)"
tmplibdir="$(mktemp -d)"
ldcfg="/etc/ld.so.conf.d/test-snippet.conf"
cleanup() {
  rm -f "$ldcfg"
  rm -rf "$tmpdir" "$tmplibdir"
}
trap cleanup EXIT
cat > "$tmpdir/ldsoconfdotd.c" << EOF
#include <stdio.h>

void ldsoconfdotd_test(void) {
  printf("Calling %s\n", __func__);
}
EOF
cat > "$tmpdir/test.c" << EOF
void ldsoconfdotd_test(void);
int main(void) {
  ldsoconfdotd_test();
}
EOF
gcc -c -fpic "$tmpdir/ldsoconfdotd.c" -o "$tmpdir/ldsoconfdotd.o"
gcc -shared -o "$tmplibdir/libldsoconfdotd.so" \
  "$tmpdir/ldsoconfdotd.o"
echo "$tmplibdir" > "$ldcfg"
ldconfig
LIBRARY_PATH="$tmplibdir" \
  gcc "$tmpdir/test.c" -o "$tmpdir/test" -lldsoconfdotd
"$tmpdir"/test

ver="${{package.version}}"
grep -qF "/usr/lib/libc.so-$ver" /usr/lib/libc.so || { cat /usr/lib/libc.so; echo "FAIL: libc.so not pinned"; exit 1; }
grep -qF "/usr/lib/libm.so-$ver" /usr/lib/libm.so || { cat /usr/lib/libm.so; echo "FAIL: libm.so not pinned"; exit 1; }
grep -q "ld-linux" /usr/lib/libc.so || { echo "FAIL: libc.so lost AS_NEEDED(ld-linux)"; exit 1; }
test -f "/usr/lib/libc.so-$ver" && test -f "/usr/lib/libm.so-$ver"
# Every file the linker scripts reference must exist. The pinned
# entries must be real files, not symlinks back into the runtime.
paths="$(cat /usr/lib/libc.so /usr/lib/libm.so | tr '()' '  ' | tr ' ' '\n' | grep '^/[a-z]' | sort -u)"
for f in $paths; do
  test -e "$f" || { echo "FAIL: linker script references missing $f"; exit 1; }
  case "$f" in
    */ld-linux*) : ;;
    *) test ! -L "$f" || { echo "FAIL: $f is a symlink, expected a pinned real file"; exit 1; }
       owned_by=$(apk info -qW "$f")
       [ "$owned_by" = "${{package.name}}-dev" ] || { echo "FAIL: $f is owned by $owned_by instead of the dev package"; exit 1;}
       ;;
  esac
done
echo "PASS: linker scripts pinned to $ver"

# This is the minimal reproducer of the glibc breakage we
# experienced when hardening was enabled.  See
# https://github.com/wolfi-dev/os/pull/53351#issuecomment-2946134881
# for more details.
cat > glibc-hardening-test.c << _EOF_
#include <execinfo.h>

int
main(int argc, char *argv[])
{
  void *a[4096];
  backtrace (a, 100);
  return 0;
}
_EOF_
gcc glibc-hardening-test.c -o glibc-hardening-test
# Run the program 1000 times to make sure that unwinding works without problems.
for i in $(seq 1000); do ./glibc-hardening-test; done

set -euo pipefail
pkg=glibc-locale-${{range.key}}
out=$(locale --all-locales) || {
  echo "FAIL: locale --all-locales failed for $pkg"
  exit 1
}
matches=$(echo "$out" | grep "^${{range.key}}") || {
  echo "FAIL: $pkg did not install any locales per 'locale --all-locales'"
  echo "$ locale --all-locales"
  echo "$out"
  exit 1
}
echo "PASS: $pkg shipped" $matches
